beginning.embedded_functions:
#include <stdlib.h>
#include <mmt_core.h>
#include <tcpip/mmt_tcpip.h>
#include <stdint.h>

static unsigned long int limit_5g_dos_ngap_initialuemessage_per_ms = 0;

void on_load(){
	const char *str = getenv("MMT_SEC_5G_DOS_NGAP_INITIALUEMESSAGE_MS_LIMIT");
	if( str == NULL ){
		mmt_info("Rule 95: no value of MMT_SEC_5G_DOS_NGAP_INITIALUEMESSAGE_MS_LIMIT: the rule is disabled" );
		return;
	}
	limit_5g_dos_ngap_initialuemessage_per_ms = strtoul( str, NULL, 0 );
	mmt_info("Rule 95: set MMT_SEC_5G_DOS_NGAP_INITIALUEMESSAGE_MS_LIMIT=%lu%s",
		limit_5g_dos_ngap_initialuemessage_per_ms,
		limit_5g_dos_ngap_initialuemessage_per_ms == 0 ? ": the rule is disabled" : "" );
}

/*
To detect DoS, we group the messages by windows of one millisecond of the
packet time (meta.utime): all the messages whose time has the same
tv_sec * 1000 + tv_usec / 1000 are in the same window.
The counter is global: it counts the messages of all the peers together.
It counts packets: several messages in one packet count as one.
The function returns true once per window, for the first message that makes
the count greater than the limit. A limit of 0 disables the rule.
*/
static inline bool em_5g_check_msg_throughput( const void *data ){
	static uint64_t last_ms = UINT64_MAX; //current ms window
	static unsigned long int counter = 0; //number of msg in the current ms window

	const struct timeval *time = (const struct timeval *) data;
	// no limit: the rule is disabled
	if( limit_5g_dos_ngap_initialuemessage_per_ms == 0 || time == NULL )
		return false;

	uint64_t millisecond = (uint64_t) time->tv_sec * 1000 + (uint64_t) time->tv_usec / 1000;

	//new window => reset the counter
	if( last_ms != millisecond ){
		counter = 0;
		last_ms = millisecond;
	}

	counter ++;
	//report only once per window: when the count goes over the limit
	return (counter == limit_5g_dos_ngap_initialuemessage_per_ms + 1);
}
